'use strict';
// out/INVENTORY.md: every piece of art, its files, size, colour count and design reference.
function render(built) {
  const groups = new Map();
  for (const b of built) { const g = b.it.group; if (!groups.has(g)) groups.set(g, []); groups.get(g).push(b); }
  const lines = [
    '# Deep32/UX art inventory', '',
    'Generated by `tools/build.js`; do not edit by hand. Every piece is drawn as code (see `src/`).',
    'Files per piece: `.pm` (XPM3), and for CDE icons also `.bm` (1-bit) and `_m.bm` (mask); PNG previews under `png/`.', '',
    `Total: ${built.length} pieces.`, '',
  ];
  const order = ['icons', 'icons/types', 'logos', 'logos/brand', 'backdrops', 'd32library'];
  for (const g of [...order.filter(g => groups.has(g)), ...[...groups.keys()].filter(g => !order.includes(g))]) {
    const list = groups.get(g);
    lines.push(`## ${g} (${list.length})`, '', '| File | Size | Colours | Rule | What | Design reference |', '|---|---|---|---|---|---|');
    for (const b of list) {
      const cols = b.c.colours().length + (b.c.mask().includes(0) ? 1 : 0);
      lines.push(`| \`${b.it.file}\` | ${b.it.w}x${b.it.h} | ${cols} | ${b.it.rule} | ${String(b.it.title).replace(/\|/g, '/')} | ${(b.it.ref || '').replace(/\|/g, '/')} |`);
    }
    lines.push('');
  }
  return lines.join('\n');
}
module.exports = { render };
